package com.madhukar.upisplitter.service;
import com.madhukar.upisplitter.dto.ApiDtos.TransactionView; import com.madhukar.upisplitter.model.PaymentTransaction; import com.madhukar.upisplitter.repository.PaymentTransactionRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class TransactionService {private final PaymentTransactionRepository repo; public TransactionService(PaymentTransactionRepository r){repo=r;} public List<TransactionView> list(String uid){return repo.findByUserIdOrderByCreatedAtDesc(uid).stream().map(x->new TransactionView(x.getId(),x.getPaymentPlanId(),x.getAmount(),x.getStatus().name(),x.getCreatedAt(),x.getUpdatedAt(),x.getCompletedAt(),x.getSequence())).toList();} public PaymentTransaction get(String uid,String id){return repo.findById(id).filter(x->x.getUserId().equals(uid)).orElseThrow();}}
